/* Requires a matching ELF32 boot entry named _start. */
OUTPUT_FORMAT(elf32-i386)
ENTRY(_start)
SECTIONS
{
    . = 1M;
    .text ALIGN(4K) : { *(.text .text.*) }
    .rodata ALIGN(4K) : { *(.rodata .rodata.*) }
    .data ALIGN(4K) : { *(.data .data.*) }
    .bss ALIGN(4K) (NOLOAD) : {
        __bss_start = .;
        *(COMMON) *(.bss .bss.*)
        __bss_end = .;
    }
    __kernel_end = .;
}

cortex-m3.body:
/* Example memory map, NOT a device definition. Add device IRQs to startup. */
ENTRY(Reset_Handler)
MEMORY {
    FLASH (rx) : ORIGIN = 0x08000000, LENGTH = 256K
    RAM (rwx) : ORIGIN = 0x20000000, LENGTH = 64K
}
__stack_top = ORIGIN(RAM) + LENGTH(RAM);
SECTIONS {
    .isr_vector : { KEEP(*(.isr_vector)) } > FLASH
    .text : { *(.text*) *(.rodata*) . = ALIGN(4); } > FLASH
    .data : {
        . = ALIGN(4); __data_start = .;
        *(.data*) . = ALIGN(4); __data_end = .;
    } > RAM AT> FLASH
    __data_load = LOADADDR(.data);
    .bss (NOLOAD) : {
        . = ALIGN(4); __bss_start = .;
        *(.bss*) *(COMMON) . = ALIGN(4); __bss_end = .;
    } > RAM
    ASSERT(__bss_end <= __stack_top - 4096, "RAM overlaps reserved stack")
}

aarch64.body:
/* Example RAM base; firmware must load ELF segments here. Single core only. */
OUTPUT_ARCH(aarch64)
ENTRY(_start)
SECTIONS {
    . = 0x40080000;
    .text : { KEEP(*(.text.boot)) *(.text*) }
    .rodata : { *(.rodata*) }
    .data : { *(.data*) }
    .bss ALIGN(16) (NOLOAD) : {
        __bss_start = .; *(.bss*) *(COMMON)
        . = ALIGN(16); __bss_end = .;
    }
    .stack ALIGN(16) (NOLOAD) : { . += 16384; __stack_top = .; }
}
